import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type" };
const respond = (body: Record<string, unknown>, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response("ok", { headers: cors });
  if (request.method !== "POST") return respond({ error: "Method not allowed." }, 405);
  const url = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const authorization = request.headers.get("Authorization") ?? "";
  if (!url || !serviceKey || !authorization) return respond({ error: "Unauthorized." }, 401);
  const caller = createClient(url, Deno.env.get("SUPABASE_ANON_KEY") ?? serviceKey, { global: { headers: { Authorization: authorization } } });
  const { data: identity, error: identityError } = await caller.auth.getUser();
  if (identityError || !identity.user) return respond({ error: "Unauthorized." }, 401);
  const userId = identity.user.id;
  const admin = createClient(url, serviceKey, { auth: { autoRefreshToken: false, persistSession: false } });
  try {
    const { data: comments, error: commentsError } = await admin.from("comments").select("id").eq("user_id", userId);
    if (commentsError) throw commentsError;
    const commentIds = (comments ?? []).map((item) => item.id);
    if (commentIds.length) {
      const { error: replyError } = await admin.from("comments").update({ parent_id: null }).in("parent_id", commentIds);
      if (replyError) throw replyError;
      const { error: likedCommentError } = await admin.from("comment_likes").delete().in("comment_id", commentIds);
      if (likedCommentError) throw likedCommentError;
    }
    const { data: groups, error: groupsError } = await admin.from("groups").select("id").eq("owner_id", userId);
    if (groupsError) throw groupsError;
    const groupIds = (groups ?? []).map((item) => item.id);
    if (groupIds.length) {
      const { error } = await admin.from("group_members").delete().in("group_id", groupIds);
      if (error) throw error;
    }
    for (const table of ["comment_likes", "comments", "group_members", "groups", "notifications", "activity", "import_jobs", "user_settings", "favorites", "anime_progress", "manga_progress", "episode_ratings", "watch_history", "bookmarks", "user_roles"]) {
      const { error } = await admin.from(table).delete().eq("user_id", userId);
      if (error) throw error;
    }
    for (const table of ["profiles", "users"]) {
      const { error } = await admin.from(table).delete().eq("id", userId);
      if (error) throw error;
    }
    const { error: authError } = await admin.auth.admin.deleteUser(userId, false);
    if (authError) throw authError;
    return respond({ deleted: true });
  } catch (error) {
    console.error("delete-account failed", error);
    return respond({ error: "Your account could not be deleted safely. No confirmation was issued." }, 500);
  }
});
